// 이 파일은 scripts/gen-weather-regions.py 가 만든다. 직접 고치지 말 것.
// 출처: packages/shared/src/weather-regions.json — 지역 목록의 유일한 출처다.
// 규칙: docs/spec/voice-and-message.md 「5-1」의 '날씨 지역은 목록에서만 고른다'.
// 안드로이드 대응: data/WeatherRegions.kt(같은 스크립트가 만든다).
import Foundation

/// 지역 목록의 나라. 공휴일 달력 국가도 같은 코드를 쓴다 — 지역을 고르면 그 나라가 공휴일 국가가 된다.
enum WeatherCountry: String, CaseIterable, Sendable {
    case kr = "KR"
    case jp = "JP"
    case us = "US"

    var code: String { rawValue }

    /// 옛 앱이 읽는 `country` 칸에 쓰는 글자. 언어와 무관하게 한국어다.
    var legacyLabel: String {
        switch self {
        case .kr: return "대한민국"
        case .jp: return "일본"
        case .us: return "미국"
        }
    }

    var names: WeatherRegionNames {
        switch self {
        case .kr: return WeatherRegionNames(ko: "대한민국", en: "South Korea", ja: "韓国")
        case .jp: return WeatherRegionNames(ko: "일본", en: "Japan", ja: "日本")
        case .us: return WeatherRegionNames(ko: "미국", en: "United States", ja: "アメリカ")
        }
    }

    func displayName(language: String = WeatherRegions.currentLanguage()) -> String {
        names.value(for: language)
    }

    /// "KR"·"jp" 같은 코드 → 나라. 모르는 코드면 nil.
    static func fromCode(_ code: String?) -> WeatherCountry? {
        guard let code else { return nil }
        return WeatherCountry(rawValue: code.trimmingCharacters(in: .whitespacesAndNewlines).uppercased())
    }
}

/// 세 언어 이름. 앱 언어가 en·ja 가 아니면 한국어를 쓴다.
struct WeatherRegionNames: Hashable, Sendable {
    let ko: String
    let en: String
    let ja: String

    func value(for language: String) -> String {
        switch language {
        case "en": return en
        case "ja": return ja
        default: return ko
        }
    }
}

/// 고를 수 있는 지역 하나. 저장·전송 값은 `key` 이고, 보이는 이름은 `displayName` 이다.
/// `seatNames` 는 날씨를 재는 대표 도시(경기 → 수원)가 지역 이름과 다를 때만 있다.
struct WeatherRegion: Hashable, Sendable, Identifiable {
    let key: String
    let country: WeatherCountry
    /// 나라 안에서의 목록 순서(1부터).
    let order: Int
    let names: WeatherRegionNames
    let seatNames: WeatherRegionNames?

    var id: String { key }
    /// 옛 앱이 읽는 `country` 칸에 쓰는 글자.
    var legacyCountry: String { country.legacyLabel }
    /// 옛 앱이 읽는 `city` 칸에 쓰는 글자(한국어 이름).
    var legacyCity: String { names.ko }

    func displayName(language: String = WeatherRegions.currentLanguage()) -> String {
        names.value(for: language)
    }

    func seatDisplayName(language: String = WeatherRegions.currentLanguage()) -> String? {
        seatNames?.value(for: language)
    }
}

