    private static let byKeyIndex: [String: WeatherRegion] = Dictionary(
        uniqueKeysWithValues: all.map { ($0.key, $0) }
    )

    /// 키 → 지역. 목록에 없는 키(옛 버전·오타)면 nil.
    static func byKey(_ key: String?) -> WeatherRegion? {
        guard let key else { return nil }
        return byKeyIndex[key.trimmingCharacters(in: .whitespacesAndNewlines)]
    }

    /// 그 나라의 지역들, 목록 순서대로.
    static func byCountry(_ country: WeatherCountry) -> [WeatherRegion] {
        all.filter { $0.country == country }
    }

    /// 지역 키 → 옛 앱이 읽는 (나라, 도시) 글자. 알람 행의 날씨 나라·도시 칸에 이걸 적는다.
    static func canonicalLabels(key: String?) -> (country: String, city: String)? {
        guard let region = byKey(key) else { return nil }
        return (region.legacyCountry, region.legacyCity)
    }

    /// 나라 표기("대한민국"·"Japan"·"アメリカ"·"US" …) → 나라. 모르는 표기면 nil.
    static func country(forLabel label: String?) -> WeatherCountry? {
        let key = aliasKey(label)
        return key.isEmpty ? nil : countryAliasIndex[key]
    }

    /// 옛 (나라, 도시) 문자열 → 지역. 못 찾으면 nil — 그 값은 서버의 옛 경로(엄격한 지오코딩)로
    /// 계속 돌고, 화면은 다시 고르라고 권한다. 규칙은 scripts/gen-weather-regions.py 의 resolve 와
    /// 글자 하나까지 같다(서버·안드로이드도 같다).
    static func resolveAlias(country: String?, city: String?) -> WeatherRegion? {
        let c = canonicalize(country)
        let t = canonicalize(city)
        if c.isEmpty && t.isEmpty { return nil }
        let code = c.isEmpty ? nil : self.country(forLabel: c)
        if c.isEmpty || code != nil {
            let first = t.contains(" ") ? String(t.prefix { $0 != " " }) : ""
            guard let hit = byKey(match(t) ?? (hasLatin(first) ? nil : match(first))) else { return nil }
            // 일본·미국이라고 적었으면 그 나라 안에서만. 대한민국은 옛 앱이 자동으로 붙인 값이라 어긋나도 받는다.
            if let code, code != .kr, hit.country != code { return nil }
            return hit
        }
        return byKey(match(canonicalize(c + " " + t)) ?? (hasLatin(c) ? nil : match(c)))
    }

    /// 로마자가 있는 낱말은 첫 낱말로 다시 찾지 않는다("Birmingham England" 가 앨라배마로 간다).
    private static func hasLatin(_ text: String) -> Bool {
        text.unicodeScalars.contains { $0.value >= 0x61 && $0.value <= 0x7A }
    }

    /// 앱이 지금 쓰는 언어(ko·en·ja). 다른 문자열과 같은 기준 — 번들이 고른 현지화다.
    static func currentLanguage(bundle: Bundle = .main) -> String {
        let code = bundle.preferredLocalizations.first
            .flatMap { Locale(identifier: $0).language.languageCode?.identifier }
        switch code {
        case "en": return "en"
        case "ja": return "ja"
        default: return "ko"
        }
    }

    /// NFKC → 소문자 → 구분 글자를 공백으로 → 공백 하나로·앞뒤 제거.
    static func canonicalize(_ raw: String?) -> String {
        guard let raw, !raw.isEmpty else { return "" }
        let folded = raw.precomposedStringWithCompatibilityMapping.lowercased()
        var spaced = String.UnicodeScalarView()
        for scalar in folded.unicodeScalars {
            spaced.append(separators.contains(scalar) ? " " : scalar)
        }
        return spaced.split(separator: " ")
            .map { String($0) }
            .joined(separator: " ")
    }

    /// 별칭 표의 열쇠 — `canonicalize` 에서 공백까지 뺀 것.
    static func aliasKey(_ raw: String?) -> String {
        canonicalize(raw).replacingOccurrences(of: " ", with: "")
    }

    private static func match(_ text: String) -> String? {
        if text.isEmpty { return nil }
        if let hit = aliasIndex[aliasKey(text)] { return hit }
        guard let stripped = stripSuffix(text) else { return nil }
        return aliasIndex[aliasKey(stripped)]
    }

    private static func stripSuffix(_ text: String) -> String? {
        for suffix in suffixes where text.hasSuffix(suffix) {
            let rest = String(text.unicodeScalars.dropLast(suffix.unicodeScalars.count))
                .trimmingCharacters(in: CharacterSet(charactersIn: " "))
            return rest.isEmpty ? nil : rest
        }
        return nil
    }

    private static let separators: Set<Unicode.Scalar> = Set(
        [0x0020, 0x0009, 0x000A, 0x000D, 0x000B, 0x000C, 0x002E, 0x002C, 0x00B7, 0x30FB, 0x0027, 0x2019, 0x0022, 0x0028, 0x0029, 0x002F, 0x005F, 0x002D, 0x3001, 0x3002].compactMap(Unicode.Scalar.init)
    )

    private static let suffixes: [String] = ["특별자치시", "특별자치도", "특별시", "광역시", " prefecture", " city", " ken", " shi", " si", " gun", " do", " to", " fu", "시", "도", "군", "都", "道", "府", "県", "市"]

